private.reference_solution:
var answers = (Console.ReadLine() ?? "").Trim().Split(' ', StringSplitOptions.RemoveEmptyEntries);
if (answers.Length != 5) Environment.Exit(1);
var key = new[] { "B", "A", "C", "B", "C" };
var score = 0;
for (var index = 0; index < answers.Length; index++)
{
    if (answers[index] is not ("A" or "B" or "C")) Environment.Exit(1);
    if (answers[index] == key[index]) score++;
}
var level = score == 5 ? "expert" : score >= 3 ? "solid" : "review";
Console.WriteLine($"score={score}/5 level={level}");

if (!int.TryParse((Console.ReadLine() ?? "").Trim(), out var count) || count < 1 || count > 100) Environment.Exit(1);
var tokens = (Console.ReadLine() ?? "").Trim().Split(' ', StringSplitOptions.RemoveEmptyEntries);
if (tokens.Length != count) Environment.Exit(1);
var scores = new List<int>(count);
foreach (var token in tokens)
{
    if (!int.TryParse(token, out var score) || score < 0 || score > 100) Environment.Exit(1);
    scores.Add(score);
}
Predicate<int> isPassed = score => score >= 60;
var results = new[] { new WorkerResult(0, 0), new WorkerResult(0, 0) };
var middle = count / 2;
var first = new Thread(() => results[0] = Analyze(scores, 0, middle, isPassed));
var second = new Thread(() => results[1] = Analyze(scores, middle, count, isPassed));
first.Start();
second.Start();
first.Join();
second.Join();
var sum = results[0].Sum + results[1].Sum;
var passed = results[0].Passed + results[1].Passed;
var average = (sum / (double)count).ToString("F2", System.Globalization.CultureInfo.InvariantCulture);
Console.WriteLine($"count={count} pass={passed} average={average}");

static WorkerResult Analyze(List<int> scores, int start, int end, Predicate<int> isPassed)
{
    long sum = 0;
    var passed = 0;
    for (var index = start; index < end; index++)
    {
        sum += scores[index];
        if (isPassed(scores[index])) passed++;
    }
    return new WorkerResult(sum, passed);
}

sealed class WorkerResult
{
    public long Sum { get; }
    public int Passed { get; }

    public WorkerResult(long sum, int passed)
    {
        Sum = sum;
        Passed = passed;
    }
}
